"""Rendering of ``Packages.gz`` and ``Release`` files.

Everything here is deterministic so that unchanged repositories produce the
same hashes; ``Release`` intentionally contains a timestamp and therefore
changes on every publication.
"""

from __future__ import annotations

import gzip
import hashlib
import io
import re
from dataclasses import dataclass
from datetime import datetime, timezone

from .deb import COPIED_FIELDS, DebInfo

#: Control fields that must never be copied from an uploaded package: they
#: describe its location inside *this* repository and are generated by us.
RESERVED_INDEX_FIELDS = frozenset(
    {"filename", "size", "md5sum", "sha1", "sha256", "sha512", "description-md5"}
)

_INVALID_FILENAME_CHARS = re.compile(r"[^A-Za-z0-9.+~_-]")


@dataclass(frozen=True)
class PackageEntry:
    package: str
    version: str
    architecture: str
    filename: str
    sha256: str
    size: int

    def to_dict(self) -> dict[str, object]:
        return {
            "package": self.package,
            "version": self.version,
            "architecture": self.architecture,
            "filename": self.filename,
            "sha256": self.sha256,
            "size": self.size,
        }


def _safe_token(value: str) -> str:
    """Make a string safe for a URL path segment without losing uniqueness.

    Uniqueness never depends on this function: the content hash is appended to
    every pool filename.
    """

    cleaned = _INVALID_FILENAME_CHARS.sub("_", value)
    return cleaned or "_"


def pool_filename(component: str, info: DebInfo, sha256: str) -> str:
    package = info.package
    bucket = package[:4] if package.startswith("lib") else package[:1]
    name = (
        f"{_safe_token(package)}_{_safe_token(info.version)}_"
        f"{info.architecture}_{sha256[:16]}.deb"
    )
    return f"pool/{component}/{bucket}/{package}/{name}"


def _render_field(key: str, value: str) -> str:
    lines = value.split("\n")
    rendered = f"{key}: {lines[0].rstrip()}\n"
    for line in lines[1:]:
        rendered += f"{line.rstrip()}\n"
    return rendered


def _stanza(info: DebInfo, entry: PackageEntry) -> str:
    control = info.field_map()
    by_lower = {key.casefold(): key for key in control}
    emitted: set[str] = set()

    def emit(key: str) -> str:
        original = by_lower.get(key.casefold())
        if original is None:
            return ""
        emitted.add(key.casefold())
        return _render_field(original, control[original])

    out = [
        _render_field("Package", info.package),
        _render_field("Version", info.version),
        _render_field("Architecture", info.architecture),
    ]
    for key in COPIED_FIELDS:
        lowered = key.casefold()
        if lowered in {"package", "version", "architecture", "description"}:
            continue
        if lowered in emitted:
            continue
        out.append(emit(key))
    # Preserve any remaining, non-reserved fields (e.g. Built-Using) in their
    # original order, but never let them override generated fields.
    for key, _value in info.fields:
        lowered = key.casefold()
        if lowered in emitted or lowered in RESERVED_INDEX_FIELDS:
            continue
        if lowered in {"package", "version", "architecture", "description"}:
            continue
        out.append(_render_field(key, control[key]))
        emitted.add(lowered)

    out.extend(
        [
            _render_field("Filename", entry.filename),
            _render_field("Size", str(entry.size)),
            _render_field("SHA256", entry.sha256),
        ]
    )
    out.append(emit("Description"))
    return "".join(part for part in out if part)


def render_packages(entries: list[tuple[DebInfo, PackageEntry]]) -> bytes:
    ordered = sorted(
        entries,
        key=lambda pair: (
            pair[1].package,
            pair[1].version,
            pair[1].architecture,
            pair[1].sha256,
        ),
    )
    body = "\n".join(_stanza(info, entry) for info, entry in ordered)
    if body:
        body += "\n"
    return body.encode("utf-8")


def gzip_bytes(data: bytes) -> bytes:
    """Compress deterministically (mtime=0, no embedded filename)."""

    buffer = io.BytesIO()
    with gzip.GzipFile(
        filename="", mode="wb", fileobj=buffer, compresslevel=9, mtime=0
    ) as stream:
        stream.write(data)
    return buffer.getvalue()


def release_date(moment: datetime | None = None) -> str:
    moment = (moment or datetime.now(timezone.utc)).astimezone(timezone.utc)
    return moment.strftime("%a, %d %b %Y %H:%M:%S UTC")


def render_release(
    *,
    origin: str,
    label: str,
    suite: str,
    component: str,
    architecture: str,
    description: str,
    indexes: list[tuple[str, int, str]],
    moment: datetime | None = None,
) -> bytes:
    """Render a Release file.

    *indexes* is a list of ``(sha256, size, relative_path)`` tuples.  Both the
    uncompressed and the gzipped ``Packages`` must be listed: APT identifies
    an index target by its uncompressed name and then picks whichever listed
    variant it can decompress, so a Release listing only ``Packages.gz`` makes
    APT 2.6 skip the index entirely.
    """

    lines = [
        f"Origin: {origin}",
        f"Label: {label}",
        f"Suite: {suite}",
        f"Codename: {suite}",
        f"Date: {release_date(moment)}",
        f"Architectures: {architecture}",
        f"Components: {component}",
        f"Description: {description}",
        "Acquire-By-Hash: yes",
        "SHA256:",
    ]
    lines.extend(f" {digest} {size} {path}" for digest, size, path in indexes)
    return ("\n".join(lines) + "\n").encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()
